<?php $title='Integraciones'; require __DIR__.'/partials/top.php';$rows=[];$keys=[];try{$q=appDb()->prepare('SELECT id,name,url,events_json,active,created_at FROM outgoing_webhooks WHERE tenant_id=? ORDER BY id DESC');$q->execute([$_SESSION['user']['tenant_id']]);$rows=$q->fetchAll();$q=appDb()->prepare('SELECT id,name,key_prefix,last_used_at,created_at,revoked_at FROM api_keys WHERE tenant_id=? ORDER BY id DESC');$q->execute([$_SESSION['user']['tenant_id']]);$keys=$q->fetchAll();}catch(Throwable $e){} ?>
